INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','easy','flashcard','Name the three lobes of the right lung.','["Superior, middle, and inferior lobes — separated by the horizontal fissure (between superior and middle) and the oblique fissure (between middle and inferior)."]','A','Mnemonic: Right lung = 3 lobes (like 3 Rs of Right). Left lung has only 2 lobes because the heart takes up space on the left.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','easy','flashcard','What is the function of Type II pneumocytes?','["Type II pneumocytes synthesise and secrete pulmonary surfactant (mainly DPPC), regenerate alveolar epithelium after injury, and convert to Type I pneumocytes to repair the alveolar surface."]','A','Memory hook: Type II = Two jobs (make surfactant + repair). They are the ''stem cells'' of the alveolar epithelium.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','easy','flashcard','What is the function of alveolar macrophages?','["Alveolar macrophages (dust cells) are the primary phagocytes of the alveolar space. They engulf inhaled particles, microorganisms, and cellular debris, and present antigens to lymphocytes. They are derived from circulating monocytes."]','A','They are the ''custodians'' of the alveolus. In smokers, macrophages become laden with carbon particles, appearing black (''anthracotic'' macrophages).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','medium','flashcard','What is the difference between anatomical dead space and physiological dead space?','["Anatomical dead space (~150 ml) is the volume of conducting airways (from nose to terminal bronchioles) that do not participate in gas exchange. Physiological dead space = anatomical dead space + alveolar dead space (alveoli that are ventilated but not perfused, V/Q → ∞). In normal lungs, physiological ≈ anatomical dead space."]','A','Physiological dead space is measured by the Bohr equation using PaCO₂. It exceeds anatomical dead space in disease states causing high V/Q units, such as pulmonary embolism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','medium','flashcard','What is a bronchopulmonary segment and why is it clinically important?','["A bronchopulmonary segment is the largest subdivision of a lobe, supplied by its own tertiary (segmental) bronchus and pulmonary artery branch, and drained by intersegmental veins. It is the smallest unit of lung that can be surgically resected without compromising adjacent tissue."]','A','Right lung: 10 segments; Left lung: 8–10 segments (lingula = equivalent of right middle lobe). Localised pneumonia, abscess, or tumour confined to a segment can be treated by segmentectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','medium','flashcard','Describe the mucociliary escalator and its clinical importance.','["The mucociliary escalator consists of ciliated epithelial cells (from trachea to terminal bronchioles) beating at ~12 Hz, propelling a mucus blanket (produced by goblet cells and submucosal glands) toward the pharynx for expectoration or swallowing. It is the primary airway defence mechanism against inhaled particles and pathogens."]','A','Damaged by smoking (cilia paralysis), cystic fibrosis (thick mucus), and primary ciliary dyskinesia (immotile cilia). Loss leads to recurrent respiratory infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','medium','flashcard','What distinguishes the respiratory zone from the conducting zone of the lung?','["Conducting zone (generations 1–16): trachea, bronchi, bronchioles, terminal bronchioles — no gas exchange, forms anatomical dead space (~150 ml). Respiratory zone (generations 17–23): respiratory bronchioles, alveolar ducts, alveolar sacs — contains alveoli and participates in gas exchange. Total respiratory zone volume ~2500–3000 ml."]','A','The transition from conducting to respiratory zone occurs at the respiratory bronchiole, which is the first airway generation to bear alveoli in its wall.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','hard','flashcard','What is the blood supply to the lung parenchyma vs. the bronchial tree?','["Lung parenchyma (gas exchange): supplied by deoxygenated blood from the pulmonary arteries (low-pressure, high-flow, right heart output). Bronchial tree (conducting airways down to terminal bronchioles): supplied by oxygenated blood from bronchial arteries (branches of descending thoracic aorta, high-pressure, low-flow). Venous drainage: bronchial veins drain to azygos system and some to pulmonary veins (true anatomical shunt ~2%)."]','A','The dual circulation explains why: (1) pulmonary embolism may not cause infarction if bronchial supply is intact; (2) bronchial artery haemorrhage causes massive haemoptysis (high pressure).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','hard','flashcard','What are J-receptors (juxtacapillary receptors) and what stimulates them?','["J-receptors (C-fibre endings) are located in the alveolar walls adjacent to pulmonary capillaries. Stimulated by: pulmonary capillary engorgement/oedema, pneumonia, inhalation of irritants, microemboli, and chemicals (capsaicin, phenyldiguanide). Response: rapid, shallow breathing; bronchoconstriction; bradycardia; hypotension. They contribute to the sensation of dyspnoea."]','A','J-receptors may explain the dyspnoea of left heart failure/pulmonary oedema and may contribute to the tachypnoea in pneumonia. Named ''juxtacapillary'' because of their position next to pulmonary capillaries.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Anatomy & Airway Structure','hard','flashcard','Describe the layers of the respiratory membrane that O₂ must cross during gas exchange.','["From alveolar lumen to capillary plasma: (1) alveolar fluid layer with surfactant; (2) alveolar epithelium (mainly Type I pneumocytes, ~0.2 µm); (3) epithelial basement membrane; (4) thin interstitial space; (5) capillary endothelial basement membrane; (6) capillary endothelium (~0.2 µm). Total thickness ~0.2–0.6 µm in healthy lungs. Total alveolar surface area ~70 m²."]','A','In pulmonary oedema and fibrosis, the interstitial space expands, increasing diffusion distance and impairing gas exchange. CO₂ (20× more soluble) is unaffected long before O₂ exchange deteriorates.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','easy','flashcard','State Laplace''s law as it applies to alveolar stability.','["P = 2T/r. The pressure required to keep an alveolus open is directly proportional to surface tension (T) and inversely proportional to the radius (r). Without surfactant, small alveoli would have higher pressure and tend to empty into larger ones (alveolar instability)."]','A','Surfactant reduces T preferentially in small alveoli (more molecules per unit area when compressed), equalising pressure and stabilising alveolar size. This prevents the ''snowball'' collapse of small into large alveoli.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','easy','flashcard','What is lung compliance and how is it calculated?','["Lung compliance (C) = ΔV/ΔP (change in volume per unit change in transpulmonary pressure). Normal total lung compliance ≈ 200 ml/cm H₂O. Measured by inflating the lung in stepwise increments (static compliance) while relaxing all muscles."]','A','Decreased C (stiff lungs): fibrosis, ARDS, pulmonary oedema, NRDS. Increased C (floppy lungs): emphysema. Work of breathing increases with both abnormalities.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','medium','flashcard','How does surfactant prevent alveolar collapse?','["Surfactant (mainly DPPC) is an amphipathic molecule that lowers the surface tension at the air-water interface inside alveoli from ~50 dynes/cm (clean water) to near 0 dynes/cm at end-expiration. By reducing surface tension, it: (1) reduces the pressure tending to collapse alveoli; (2) increases compliance; (3) stabilises alveoli of different sizes; (4) reduces fluid transudation into alveoli."]','A','Without surfactant (NRDS in premature infants): high surface tension → progressive alveolar collapse → stiff lungs → enormous inspiratory work. Treatment: exogenous surfactant + CPAP/mechanical ventilation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','medium','flashcard','Define pleural pressure and explain its role in lung expansion.','["Pleural pressure (Ppl) is the pressure in the fluid layer between the visceral and parietal pleura. At rest (end-expiration), Ppl ≈ −5 cm H₂O (subatmospheric). During inspiration, Ppl decreases to −7.5 cm H₂O, expanding the lungs. The negative Ppl is maintained by the elastic recoil of the lungs pulling away from the chest wall and continuous lymphatic drainage of pleural fluid."]','A','Pneumothorax: air enters pleural space → Ppl rises toward 0 → lung collapses. Tension pneumothorax: Ppl becomes positive → lung fully collapses + mediastinal shift → emergency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','medium','flashcard','What determines airway resistance and how is it affected in COPD?','["Airway resistance (Raw) = driving pressure / flow rate = (Palveolar − Patmospheric) / Flow. Resistance is inversely proportional to the 4th power of radius (Poiseuille). Airway resistance is greatest in medium-sized bronchi (generations 3–5) collectively. In COPD: (1) mucus hypersecretion narrows airways; (2) inflammation causes mucosal oedema; (3) loss of radial traction (emphysema) allows small airway collapse on expiration — all dramatically increase Raw."]','A','Bronchodilators (beta-2 agonists, anticholinergics) reduce Raw by dilating airways. In emphysema, loss of radial traction causes airway collapse during forced expiration — hence dynamic airflow obstruction and air trapping.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','medium','flashcard','What are the primary inspiratory muscles and their roles?','["Primary inspiratory muscle: diaphragm (accounts for ~70% of quiet inspiration; innervated by phrenic nerve C3–C5). Accessory: external intercostals (raise rib cage), sternocleidomastoid (lifts sternum), scaleni (lift first two ribs). During heavy exercise: all accessory muscles recruited. During normal quiet breathing, expiration is passive (elastic recoil); active expiration (internal intercostals, abdominals) only during forced breathing or exercise."]','A','''C3,4,5 keeps the diaphragm alive.'' Diaphragmatic paralysis (phrenic nerve injury, e.g., from cervical cord injury at C3–5) causes respiratory failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','hard','flashcard','Explain the concept of flow limitation during forced expiration and its clinical relevance.','["During forced expiration, positive pleural pressure is transmitted to airways. At the equal pressure point (EPP), airway luminal pressure equals pleural pressure. Downstream (mouthward) from the EPP, pleural pressure exceeds luminal pressure — airways collapse. Further expiratory effort simply collapses airways more proximally, not increasing flow. This creates an effort-independent maximum expiratory flow, determined by lung recoil and upstream airway conductance — not effort."]','A','Clinical relevance: FEV1 is effort-independent (after 20–25% of FVC) in healthy individuals. In COPD, the EPP moves upstream (into smaller airways) causing greater collapse and more severe flow limitation. Flow-volume loops show the characteristic scooped expiratory curve.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','hard','flashcard','How does auto-PEEP (intrinsic PEEP) develop in mechanically ventilated COPD patients?','["Auto-PEEP (intrinsic PEEP) occurs when expiration time is insufficient for complete lung emptying before the next breath, leaving residual positive alveolar pressure above applied PEEP. In COPD: high airway resistance + dynamic airway collapse prolong expiratory time constant (τ = R × C). Rapid ventilator rates compound this. Auto-PEEP causes: dynamic hyperinflation, increased WOB, haemodynamic compromise (impaired venous return), and barotrauma risk."]','A','Detected by an expiratory hold manoeuvre on the ventilator. Managed by: increasing expiratory time (lower RR, I:E ratio 1:3 to 1:5), bronchodilators to reduce R, and accepting mild permissive hypercapnia.','universal',true,'{year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','hard','flashcard','Explain why emphysema increases static lung compliance but worsens dynamic lung function.','["Static compliance is increased in emphysema because destruction of alveolar walls (elastin/collagen matrix) reduces the elastic recoil of the lung tissue — lungs are ''floppier'' and easier to inflate. However, this same loss of elastin destroys the radial traction holding small airways open. During forced expiration, unsupported small airways collapse early (low EPP), causing air trapping (elevated RV and FRC), reduced FEV1, and low FEV1/FVC despite high static compliance."]','A','This explains the paradox: emphysema lungs are ''easy to fill but hard to empty.'' TLC is elevated (high C), but RV is also elevated (airway collapse), and FEV1/FVC is severely reduced.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Pulmonary Mechanics','hard','flashcard','What is the significance of the time constant (τ) in pulmonary mechanics?','["Time constant τ = Resistance (R) × Compliance (C). It represents the time for a lung unit to fill or empty to 63% of its final volume. After 3τ, ~95% filling/emptying. Regional differences in τ cause uneven ventilation: lung units with high R or high C fill slowly (slow units) — receive more ventilation at low respiratory rates; at high rates, fast units fill preferentially, worsening V/Q distribution."]','A','In COPD: high R → long τ → air trapping. In ARDS: low C → short τ (stiff units fill faster) but collapsed units may not open at all. Ventilator settings must account for τ to prevent over- or under-ventilation of lung units.','universal',false,'{year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','easy','flashcard','State the four lung volumes and their approximate values in a healthy adult male.','["(1) Tidal volume (Vt) ≈ 500 ml — volume per normal breath. (2) Inspiratory reserve volume (IRV) ≈ 3000 ml — extra volume after normal inspiration. (3) Expiratory reserve volume (ERV) ≈ 1100 ml — extra volume after normal expiration. (4) Residual volume (RV) ≈ 1200 ml — remains after maximal expiration; cannot be measured by spirometry."]','A','Mnemonic: Tiny IRV ERVs RVing. The four volumes add up to TLC ≈ 5800 ml. Women''s volumes are 20–30% less than men''s.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','easy','flashcard','Define Functional Residual Capacity (FRC) and explain why it is clinically important.','["FRC = ERV + RV ≈ 2300 ml. It is the volume remaining in the lungs after a normal passive expiration. FRC is the equilibrium point where lung inward recoil equals chest wall outward recoil (no muscle activity). Clinically important because: (1) it acts as a buffer against extreme O₂/CO₂ swings between breaths; (2) it is altered in disease (↑ in emphysema, ↓ in fibrosis, obesity, supine posture, ARDS); (3) it cannot be measured by spirometry."]','A','FRC can be measured by: helium dilution, nitrogen washout, or body plethysmography. FRC is reduced in the supine position by ~0.7 L — important in anaesthesia, critical illness, and post-operative care.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','medium','flashcard','What is FEV1/FVC ratio, and how does it differentiate obstructive from restrictive disease?','["FEV1/FVC is the fraction of forced vital capacity expired in the first second. Normal ≥ 0.80. In obstructive disease (asthma, COPD): FEV1 falls more than FVC → FEV1/FVC < 0.70 (LLN). In restrictive disease (fibrosis, effusion): both FEV1 and FVC fall proportionally → FEV1/FVC is normal or elevated (>0.80), but TLC is reduced."]','A','The ratio is the key spirometric discriminator. If both FEV1 and FVC are reduced with a normal ratio: think restriction. If ratio is low: think obstruction. A mixed pattern exists when both are abnormal simultaneously.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','medium','flashcard','Describe the flow-volume loop in obstructive versus restrictive lung disease.','["Normal: symmetric bell-shaped peak; tall linear expiratory limb. Obstructive (COPD/asthma): reduced peak flow; concave (scooped) expiratory limb indicating reduced mid and late expiratory flows (FEF25–75% reduced); FVC may be reduced due to air trapping. Restrictive (fibrosis): small loop; peak flow relatively preserved or slightly reduced; steep, linear expiratory limb; all volumes reduced; FVC markedly reduced."]','A','The inspiratory limb also gives information: variable extrathoracic obstruction flattens the inspiratory limb; fixed obstruction flattens both. Fixed intrathoracic obstruction selectively flattens the expiratory limb.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','medium','flashcard','How is FRC measured when spirometry is insufficient?','["FRC cannot be measured by spirometry (contains RV). Methods: (1) Helium dilution: equilibrate known He concentration into lungs from FRC; He concentration falls proportionally to FRC. (2) Nitrogen washout: breathe 100% O₂, wash out N₂; total N₂ expired allows FRC calculation. (3) Body plethysmography (gold standard): uses Boyle''s law — panting against closed shutter; changes in box pressure and mouth pressure allow calculation of all thoracic gas volume including trapped gas."]','A','Body plethysmography gives the largest (most accurate) values in emphysema/bullous disease because it measures all intrathoracic gas, including gas trapped in non-communicating bullae.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','medium','flashcard','What changes in lung volumes occur in COPD and why?','["In COPD: RV increased (air trapping from early airway closure); FRC increased (hyperinflation); TLC increased or normal (in pure emphysema); VC decreased; FEV1 markedly decreased; FEV1/FVC decreased (<0.70); ERV decreased. Mechanisms: (1) emphysematous destruction → loss of radial traction → small airway collapse trapping air; (2) mucus/inflammation obstructs airways; (3) chest wall adapts to new higher resting volume (barrel chest)."]','A','In severe COPD, the diaphragm is flattened by hyperinflation, reducing its mechanical advantage — worsening respiratory muscle inefficiency. IC decreases because TLC cannot increase proportionally to match the raised FRC.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','medium','flashcard','What is closing capacity and when does it exceed FRC?','["Closing capacity (CC) = closing volume (CV) + RV. CV is the lung volume at which small airways begin to close during expiration. Normally CC < FRC, so airways remain open throughout tidal breathing. CC exceeds FRC in: elderly patients (age-related airway loss), obese patients (FRC reduced), supine position (FRC falls by ~0.7 L), smokers, and patients with early small airway disease."]','A','When CC > FRC, airway closure during tidal breathing causes gas trapping and V/Q mismatch → hypoxaemia. This explains why elderly patients have lower PaO₂ and why SpO₂ falls rapidly in the supine obese patient.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','hard','flashcard','How does the relationship between RV and TLC change in obstructive vs restrictive disease?','["Normal: RV/TLC ≈ 25% (e.g., 1200/5800). In obstructive disease (emphysema/COPD): both TLC (mild increase) and RV (marked increase from air trapping) increase, so RV/TLC ratio rises significantly (>35–40%), indicating hyperinflation. In restrictive disease: both TLC and RV decrease proportionally, so RV/TLC ratio may be normal or slightly increased (if small airways close early at higher absolute lung volumes despite smaller TLC)."]','A','RV/TLC > 35% is a sensitive marker of air trapping in obstructive disease. In severe COPD, RV/TLC can reach 50–60%.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','hard','flashcard','What is peak expiratory flow rate (PEFR) and what limits it?','["PEFR is the maximum airflow rate achievable during a forced expiration from TLC. Normal values: ~600 L/min (men), ~450 L/min (women). It is effort-dependent in the first 20 ms, then becomes effort-independent (determined by airway calibre and elastic recoil). PEFR is reduced in obstructive disease (asthma, COPD) and is used for home monitoring of asthma — >20% diurnal variation or fall of >50 L/min indicates significant airflow variability."]','A','PEFR is a simple, inexpensive point-of-care test. However, it correlates poorly with FEV1 in some patients and is highly effort-dependent — a poor effort can give falsely reassuring results. FEV1 from full spirometry is more reliable for diagnosis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Lung Volumes & Capacities','hard','flashcard','Explain the ''gas trapping'' mechanism in severe asthma and its haemodynamic consequence (pulsus paradoxus).','["In severe asthma, widespread dynamic airway obstruction and mucus plugging cause air trapping (elevated FRC, RV). The patient breathes at high lung volumes. During inspiration, the large negative intrathoracic pressure needed to overcome resistance: (1) increases venous return to the right heart; (2) reduces LV filling (increased LV afterload via RV distension and pericardial constraint); (3) reduces systolic BP by >10 mmHg on inspiration — pulsus paradoxus."]','A','Pulsus paradoxus >10 mmHg indicates severe asthma (or cardiac tamponade). Measured by sphygmomanometer: inflate cuff above systolic; deflate slowly; note pressure at which first sound appears during expiration vs inspiration — difference > 10 mmHg is paradoxical.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','easy','flashcard','State the alveolar ventilation equation and explain its clinical significance.','["VA = (Vt − VD) × RR, where VA = alveolar ventilation, Vt = tidal volume (~500 ml), VD = dead space (~150 ml), RR = respiratory rate. Also: PACO₂ = VCO₂/VA × k. Clinical significance: (1) Rapid shallow breathing dramatically reduces VA (e.g., Vt 200 ml, RR 20 → VA = 50 × 20 = 1000 ml/min vs. normal ~4200 ml/min); (2) Doubling VA halves PaCO₂; halving VA doubles PaCO₂."]','A','Clinically: a patient who takes rapid, shallow breaths may appear to be ''breathing'' but have inadequate alveolar ventilation, leading to CO₂ retention — the ''silent'' danger of rapid shallow breathing patterns.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','easy','flashcard','What is the alveolar gas equation and how is it used clinically?','["PAO₂ = PiO₂ − (PACO₂/R), where PiO₂ = FiO₂ × (PB − 47), PACO₂ ≈ PaCO₂, R = respiratory quotient (0.8). At sea level, room air: PAO₂ = 0.21 × (760 − 47) − 40/0.8 = 149.7 − 50 ≈ 100 mmHg. Used to calculate the A-a gradient: A-a gradient = PAO₂ − PaO₂ (normal 5–15 mmHg, rising with age)."]','A','An elevated A-a gradient indicates an intrinsic lung abnormality (shunt, V/Q mismatch, diffusion impairment). Normal A-a with low PaO₂ suggests hypoventilation as the cause (e.g., opioid overdose — low PaCO₂ alone explains low PaO₂).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','medium','flashcard','How does the Bohr equation measure physiological dead space?','["Bohr equation: VD/Vt = (PaCO₂ − PeCO₂) / PaCO₂, where PaCO₂ = arterial CO₂ (= alveolar CO₂, since all expired CO₂ comes from perfused alveoli), PeCO₂ = mean expired PCO₂. Rearranged: VD = Vt × (PaCO₂ − PeCO₂) / PaCO₂. Normal VD/Vt ≈ 0.30. Dead space fraction >0.60 usually requires mechanical ventilation."]','A','The Bohr equation identifies the dilution of alveolar CO₂ by dead space gas (which contains no CO₂). An elevated VD/Vt ratio in pulmonary embolism or ARDS increases the work of breathing needed to maintain normal PaCO₂.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','medium','flashcard','Explain why pulmonary embolism increases physiological dead space.','["Pulmonary embolism blocks pulmonary arterial flow to ventilated lung segments. Those segments continue to be ventilated (V remains) but receive no blood flow (Q → 0) → V/Q → infinity → alveolar dead space. Total physiological dead space = anatomical + alveolar dead space increases. If not compensated by increased ventilation, PaCO₂ rises. The patient often hyperventilates to maintain PaCO₂, leading to low PaCO₂ and respiratory alkalosis."]','A','In PE: PaCO₂ often low (hyperventilation); A-a gradient elevated; D-dimer raised; CT pulmonary angiography confirms. The low PaCO₂ in PE is from compensatory hyperventilation, not from the embolism itself.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','medium','flashcard','Compare the effects of rapid shallow breathing vs slow deep breathing on alveolar ventilation.','["Rapid shallow (Vt 200 ml, RR 20, VD 150 ml): VA = (200−150) × 20 = 1000 ml/min. Slow deep (Vt 700 ml, RR 8, VD 150 ml): VA = (700−150) × 8 = 4400 ml/min. Both give the same minute ventilation (4000 ml/min), but alveolar ventilation differs dramatically. Deep slow breathing is far more efficient because a smaller fraction of each breath is wasted on dead space."]','A','This explains why rapid shallow breathing (e.g., in pain, anxiety, splinting post-surgery) can cause CO₂ retention despite apparently adequate respiratory rate. Adequate minute ventilation does NOT guarantee adequate alveolar ventilation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','medium','flashcard','What is the effect of PEEP on dead space in mechanically ventilated patients?','["PEEP increases mean airway pressure and alveolar pressure. If PEEP exceeds pulmonary arterial pressure (Zone 1 conditions), capillaries are compressed → alveoli ventilated but not perfused → alveolar dead space increases. Paradoxically, PEEP that recruits previously collapsed alveoli can decrease V/Q mismatch and total dead space. The net effect depends on the balance between alveolar recruitment (reduces dead space) and Zone 1 creation (increases dead space)."]','A','High PEEP in ARDS: usually reduces dead space by recruiting collapsed alveoli (net beneficial). In normal lungs or in patients with low cardiac output (shock), high PEEP predominantly creates Zone 1 dead space — raising PaCO₂.','universal',false,'{year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','hard','flashcard','A patient has VT 600 ml, RR 15/min, PaCO₂ 40 mmHg, PeCO₂ 28 mmHg. Calculate physiological dead space and dead space fraction.','["VD = Vt × (PaCO₂ − PeCO₂)/PaCO₂ = 600 × (40 − 28)/40 = 600 × 0.30 = 180 ml. Dead space fraction (VD/Vt) = 180/600 = 0.30 (30%). Alveolar ventilation = (600 − 180) × 15 = 6300 ml/min. This is a normal VD/Vt. If VD/Vt rose to 0.60, VA would halve and PaCO₂ would double to ~80 mmHg unless Vt or RR increased to compensate."]','A','Normal VD/Vt ≈ 0.25–0.35. In severe ARDS or massive PE, VD/Vt can exceed 0.60–0.80, severely compromising CO₂ elimination and requiring high minute ventilation (which itself stresses the lung).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','hard','flashcard','Explain regional differences in alveolar ventilation in the upright lung.','["In the upright lung, pleural pressure is more negative at the apex (−10 cm H₂O) and less negative at the base (−2.5 cm H₂O) due to gravity (lung weight). This means apical alveoli are more inflated at FRC (operating on a flatter, less compliant portion of their pressure-volume curve) and receive less ventilation per breath. Basal alveoli are less inflated at FRC (steeper, more compliant portion) and receive more ventilation per breath. Ventilation is therefore greater at the bases than the apices (~3:1)."]','A','The gradient of pleural pressure (~0.25 cmH₂O/cm height) means lower lung alveoli start more collapsed at FRC but have more ''room to expand'' per cmH₂O pressure change → more compliant at FRC → receive more ventilation. This matches perfusion distribution, optimising V/Q ratio.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','hard','flashcard','What is the iso-shunt diagram and how is it used in clinical practice?','["The iso-shunt diagram plots PaO₂ against FiO₂ for different levels of true shunt (0%, 10%, 20%, 30%, 50%). It allows estimation of shunt fraction from PaO₂ measured at a given FiO₂. Example: PaO₂ of 60 mmHg on FiO₂ 0.50 suggests ~20% shunt. The key concept is that true shunt cannot be corrected by increasing FiO₂ — the shunt line becomes flat at high FiO₂. V/Q mismatch lines converge toward normal PaO₂ with rising FiO₂."]','A','Clinically, a patient not responding to high FiO₂ (>50%) supplemental O₂ should be suspected of having a significant shunt (e.g., ARDS, massive atelectasis, intracardiac shunt, hepatopulmonary syndrome). This guides the decision to start PEEP or investigate for structural shunts.','universal',false,'{year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Ventilation & Dead Space','hard','flashcard','How does low V/Q (not true shunt) cause hypoxaemia, and why does supplemental O₂ correct it?','["In low V/Q units (e.g., partially obstructed airways), ventilation is reduced but not zero. Alveolar PO₂ in these units is low (between venous and normal alveolar values). Blood leaving them has low PO₂. When this is mixed with blood from normal units, overall PaO₂ falls. However, because ventilation is not zero, supplemental O₂ can raise alveolar PO₂ in these low V/Q units, increasing O₂ content of blood from those units and correcting hypoxaemia."]','A','Key distinction: Low V/Q → corrects with O₂. True shunt (V/Q = 0) → does NOT correct with O₂ (blood never contacts ventilated alveoli regardless of FiO₂). Clinically tested: if PaO₂ rises to >400 mmHg on 100% O₂, shunt fraction is minimal.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','easy','flashcard','State Fick''s law of diffusion as applied to pulmonary gas exchange.','["Rate of diffusion = (A × D × ΔP) / T, where A = surface area (~70 m² in healthy lungs), D = diffusion coefficient (proportional to gas solubility, inversely proportional to √molecular weight), ΔP = partial pressure difference across membrane, T = membrane thickness (~0.2–0.6 µm). CO₂ diffuses ~20× faster than O₂ despite being heavier because its solubility is ~24× greater."]','A','Mnemonic: ''SADPT'' — Surface area, And Diffusivity, Pressure difference, divided by Thickness. Clinical reductions in gas exchange: ↓A (emphysema), ↑T (oedema/fibrosis), ↓ΔP (altitude/hypoventilation), ↓D (rare).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','easy','flashcard','What is the normal capillary transit time for blood in pulmonary capillaries, and how does this relate to gas exchange?','["Normal pulmonary capillary transit time ≈ 0.75 seconds at rest. O₂ equilibrates with alveolar gas in ~0.25 seconds (end of first third of transit) — considerable reserve for equilibration. During strenuous exercise, transit time falls to ~0.25 seconds; in healthy lungs, O₂ still equilibrates fully. In diffusion-impaired lungs (fibrosis, ARDS), O₂ cannot equilibrate in the shortened transit time during exercise — causing exercise-induced hypoxaemia."]','A','This explains why patients with fibrosis can maintain normal PaO₂ at rest (0.75 s is adequate despite thickened membrane) but desaturate on exertion (transit time shortens to 0.25 s → equilibration fails). This is ''diffusion-limited exercise desaturation.''','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','medium','flashcard','Distinguish between perfusion-limited and diffusion-limited gas exchange with examples.','["Perfusion-limited gas exchange: the gas equilibrates rapidly across the membrane; further uptake depends only on increasing blood flow. Example: N₂O, O₂ (normally), CO₂. Diffusion-limited: the gas does not fully equilibrate during transit time; a partial pressure gradient persists at the end of the capillary. Example: CO (very high Hb affinity keeps PCO near zero), O₂ during exercise in fibrosis, O₂ at altitude with high cardiac output."]','A','CO is the extreme diffusion-limited example — Hb binds CO so avidly that blood PCO stays near 0 throughout transit, maintaining a maximum gradient. This property makes CO ideal for measuring DLCO.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','medium','flashcard','What is DLCO, what does it measure, and what causes it to decrease?','["DLCO (diffusing capacity for CO) = rate of CO uptake (ml/min) / alveolar PCO (mmHg). It reflects: (1) alveolar surface area for gas exchange; (2) alveolar membrane thickness; (3) pulmonary capillary blood volume. Reduced DLCO: emphysema (↓ surface area), pulmonary fibrosis (↑ thickness, ↓ surface area), pulmonary hypertension (↓ capillary blood volume), pulmonary embolism. Elevated DLCO: polycythaemia, left-to-right shunt, pulmonary haemorrhage (extra Hb in alveolar space)."]','A','DLCO is the single most sensitive spirometric test for emphysema (reduced before flow limitation becomes obvious) and the key test for interstitial lung disease severity. It is measured by single-breath CO technique (10-second breath-hold).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','medium','flashcard','Explain the causes and mechanisms of hypoxaemia — the five mechanisms.','["(1) Hypoventilation: ↑PaCO₂ → ↓PAO₂ (alveolar gas equation); A-a gradient normal. (2) V/Q mismatch (commonest): regions of low V/Q contribute venous-like blood; A-a gradient elevated; corrects with O₂. (3) Shunt: blood bypasses ventilated alveoli; A-a gradient elevated; does NOT correct with O₂. (4) Diffusion impairment: thickened membrane/reduced surface area; A-a gradient elevated; worst on exercise. (5) Low inspired PO₂: altitude; A-a gradient normal."]','A','Quick clinical approach: (1) check A-a gradient; (2) if normal → hypoventilation or altitude; (3) if elevated → shunt, V/Q mismatch, or diffusion; (4) give 100% O₂: corrects V/Q mismatch but NOT true shunt.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','medium','flashcard','How are partial pressures of gases calculated and what is Dalton''s law?','["Dalton''s law: in a gas mixture, each gas exerts its own partial pressure independently of others. Partial pressure = fractional concentration × total pressure. At sea level (PB = 760 mmHg, PH₂O = 47 mmHg at body temperature): PO₂ (inspired) = 0.21 × (760 − 47) = 149.7 mmHg; PCO₂ (inspired) = 0.0003 × 713 ≈ 0.23 mmHg; PN₂ (inspired) ≈ 563 mmHg. Water vapour pressure must be subtracted from total pressure before calculating alveolar gas values."]','A','Water vapour pressure at body temperature (37°C) is always 47 mmHg regardless of altitude — it fully saturates inspired air in the airways. This is why altitude reduces PAO₂ more than expected from barometric pressure alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','hard','flashcard','Explain how pulmonary oedema impairs gas exchange via multiple mechanisms.','["Pulmonary oedema impairs gas exchange by: (1) Increasing diffusion distance — alveolar fluid and interstitial fluid widen the diffusion path for O₂; (2) Reducing functional alveolar surface area — fluid-filled alveoli cannot participate in gas exchange (shunt, V/Q = 0); (3) Reducing compliance — fluid-filled alveoli require higher inflation pressures, increasing work of breathing; (4) Stimulating J-receptors — causing tachypnoea and dyspnoea; (5) Promoting atelectasis — surfactant dilution in oedema fluid reduces surface tension maintenance."]','A','In cardiogenic pulmonary oedema: raised pulmonary capillary wedge pressure forces fluid through the Starling mechanism. In non-cardiogenic (ARDS): increased permeability floods alveoli with protein-rich exudate. Both create diffuse bilateral opacification and severe hypoxaemia.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','hard','flashcard','Why is CO₂ elimination rarely impaired by diffusion limitation, while O₂ often is?','["CO₂ is ~24 times more soluble in tissue fluid than O₂, giving it a diffusion coefficient ~20 times greater (Fick''s law: D ∝ solubility/√mol.wt). Therefore CO₂ equilibrates across the respiratory membrane ~20× faster. Even with doubled membrane thickness (fibrosis), CO₂ equilibrates in a fraction of the 0.75-second transit time. O₂, being less soluble and having a lower pressure gradient, is more vulnerable to diffusion limitation when membrane thickness increases or transit time shortens."]','A','Clinical consequence: in early/moderate interstitial lung disease, PaCO₂ is often normal or low (from hyperventilation) while PaO₂ is impaired. CO₂ retention due to diffusion limitation alone is essentially never seen; CO₂ retention implies hypoventilation or severe V/Q mismatch.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','hard','flashcard','A patient with hepatopulmonary syndrome (HPS) has PaO₂ that improves minimally with 100% O₂. What is the mechanism of hypoxaemia?','["HPS is characterised by intrapulmonary vascular dilatations (IPVDs) — dilated pulmonary capillaries (up to 100 µm diameter vs normal 7–15 µm). Three mechanisms of hypoxaemia: (1) Diffusion limitation — O₂ cannot reach red cells in the centre of dilated capillaries; (2) True shunt — some IPVDs are arteriovenous-like connections (V/Q = 0); (3) V/Q mismatch — non-uniform perfusion. The shunt component explains poor response to 100% O₂ (orthodeoxia — PaO₂ falls on standing as basilar IPVDs open more with upright posture)."]','A','Orthodeoxia + platypnoea (dyspnoea worse sitting up, better lying down) is the hallmark of HPS — the opposite of most pulmonary conditions. Liver transplantation reverses HPS as portal hypertension resolves.','universal',true,'{year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Gas Exchange & Diffusion','hard','flashcard','How does anaemia differ from hypoxaemia in terms of O₂ delivery and tissue hypoxia?','["Hypoxaemia: reduced PaO₂ and SaO₂ → reduced O₂ content (CaO₂); both dissolved and Hb-bound O₂ reduced; A-a gradient may be elevated. Anaemia: normal PaO₂ and SaO₂ (normal gas exchange); reduced CaO₂ due to reduced Hb concentration → reduced O₂ delivery (DO₂ = CO × CaO₂). In anaemia, the O₂-Hb curve is normal, so Hb is fully saturated. Tissue hypoxia occurs from reduced O₂ delivery, not impaired gas exchange. DLCO is normal in anaemia."]','A','Key distinction: pulse oximetry (SpO₂) is NORMAL in anaemia (Hb is fully saturated). SpO₂ measures % saturation, not content. A patient can have normal SpO₂ but severely reduced O₂ delivery. Hb level must be checked separately.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','easy','flashcard','Describe the shape of the oxygen-haemoglobin dissociation curve and its physiological significance.','["The O₂-Hb dissociation curve is sigmoid (S-shaped) due to cooperative binding (binding of one O₂ increases affinity for subsequent O₂ molecules — allosteric transition from T-state to R-state). Key points: PO₂ 100 mmHg → SaO₂ ~98%; PO₂ 60 mmHg → SaO₂ ~90% (steep decline begins here); PO₂ 40 mmHg → SaO₂ ~75% (mixed venous). The flat upper portion stabilises arterial SaO₂ despite moderate falls in PaO₂ (protective); the steep lower portion enables efficient O₂ unloading at tissues."]','A','The threshold at PO₂ 60 mmHg (SaO₂ 90%) is clinically critical — below this, SaO₂ falls steeply. O₂ therapy targets PaO₂ >60 mmHg to remain on the safe, flat part of the curve. SpO₂ <90% requires urgent intervention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','easy','flashcard','What is oxygen delivery (DO₂) and how is it calculated?','["DO₂ = CO × CaO₂, where CO = cardiac output (~5 L/min), CaO₂ = arterial O₂ content = (1.34 × Hb × SaO₂) + (0.003 × PaO₂). Normal: DO₂ = 5 × 20 ml/dl = 1000 ml/min. Normal VO₂ = 250 ml/min, so O₂ extraction ratio ≈ 25% (considerable reserve). DO₂ is reduced by: low CO (cardiogenic shock), low Hb (anaemia), low SaO₂ (respiratory failure), or any combination."]','A','The three pillars of O₂ delivery: Pump (cardiac output), Pipe (haemoglobin), and P (PO₂/SaO₂). To optimise O₂ delivery in shock: fluids/inotropes (CO), transfusion (Hb), supplemental O₂ (SaO₂).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','medium','flashcard','List the factors that shift the O₂-Hb dissociation curve to the right (decreased affinity) and explain their physiological benefit.','["Rightward shift (increased P50, decreased O₂ affinity — promotes O₂ release to tissues): (1) Increased PCO₂ (Bohr effect); (2) Decreased pH / increased H⁺ (Bohr effect); (3) Increased temperature; (4) Increased 2,3-DPG. These factors are all elevated in metabolically active tissues — so Hb releases O₂ precisely where it is most needed. In pulmonary capillaries, the reverse applies (lower PCO₂, higher pH → leftward shift → favours O₂ loading)."]','A','Memory: ''CADET face RIGHT'' — CO₂, Altitude adaptations (2,3-DPG), DEcrease in pH, Temperature. The Bohr effect is a 2-for-1 benefit: tissues generate CO₂ and H⁺, both of which shift the curve rightward, enhancing O₂ delivery to those very tissues.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','medium','flashcard','Explain the pathophysiology and management of carbon monoxide (CO) poisoning.','["CO binds haemoglobin with ~240× greater affinity than O₂, forming COHb. Mechanisms of toxicity: (1) Reduces O₂-carrying capacity (COHb cannot carry O₂); (2) Leftward shift of O₂-Hb curve (remaining oxyHb holds O₂ more tightly → impaired tissue O₂ release); (3) Binds cytochrome c oxidase (inhibits mitochondrial respiration). Management: 100% O₂ (reduces COHb half-life from ~5h in room air to ~60–90 min); hyperbaric O₂ (reduces half-life to ~20–30 min) for severe poisoning."]','A','Beware: pulse oximetry cannot distinguish COHb from OHb — SpO₂ appears normal despite life-threatening poisoning. Must use CO-oximetry (arterial blood gas with co-oximeter) to measure COHb directly.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','medium','flashcard','What is the role of 2,3-DPG in oxygen transport?','["2,3-Diphosphoglycerate (2,3-DPG) is produced by RBCs via the Rapoport-Luebering shunt of glycolysis. It binds preferentially to deoxy-Hb (in the central cleft between beta chains), stabilising the deoxy (T) state and reducing O₂ affinity (rightward shift, ↑P50). Increased in: chronic hypoxaemia, anaemia, high altitude, hyperthyroidism. Decreased in: banked blood (after 2–3 weeks), hypothyroidism, acidosis (acutely)."]','A','Banked blood loses 2,3-DPG over time → stored blood may not release O₂ efficiently to tissues immediately after transfusion. 2,3-DPG levels normalise within 24 hours of transfusion as RBC metabolism restores normal levels.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','medium','flashcard','Compare adult haemoglobin (HbA) and foetal haemoglobin (HbF) in terms of structure and O₂ affinity.','["HbA: 2α + 2β chains; P50 ≈ 27 mmHg; binds 2,3-DPG in β-chain cleft. HbF: 2α + 2γ chains; P50 ≈ 20 mmHg (leftward shift); γ chains bind 2,3-DPG less avidly → less 2,3-DPG effect → higher O₂ affinity. HbF''s higher O₂ affinity allows the fetus to extract O₂ from maternal blood across the placenta (maternal O₂-Hb curve dissociates at placental PO₂ ~50 mmHg, loading onto HbF)."]','A','Double Bohr effect: at the placenta, maternal HbA releases CO₂ → maternal blood becomes more alkaline (leftward shift, less O₂ release — actually helps). Fetal CO₂ enters maternal blood → favours maternal O₂ release; fetal Hb loads O₂. This elegant system maximises placental O₂ transfer.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','hard','flashcard','A patient has PaO₂ = 95 mmHg, SaO₂ = 98%, Hb = 5 g/dl. Calculate CaO₂ and DO₂ (CO = 5 L/min). Why is this patient at risk despite normal gas exchange?','["CaO₂ = (1.34 × 5 × 0.98) + (0.003 × 95) = 6.57 + 0.29 = 6.86 ml/dl (~7 ml/dl). Normal CaO₂ ≈ 20 ml/dl. DO₂ = 5 L/min × 70 ml/L = 350 ml/min. Normal DO₂ ≈ 1000 ml/min. Normal VO₂ ≈ 250 ml/min — O₂ delivery is barely above consumption. Any increase in O₂ demand (fever, exertion) will cause tissue hypoxia despite normal SpO₂ and PaO₂."]','A','This illustrates that normal SpO₂ (and PaO₂) does NOT exclude life-threatening tissue hypoxia in severe anaemia. Mixed venous O₂ saturation (SvO₂) would be very low, indicating near-maximal O₂ extraction. Transfusion is indicated.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','hard','flashcard','Describe the biochemical mechanism of the Bohr effect at the molecular level.','["The Bohr effect occurs because CO₂ and H⁺ bind to specific sites on deoxyhaemoglobin and stabilise the T (tense/deoxy) state. (1) CO₂ reacts with N-terminal amino groups of α and β chains to form carbamino compounds (–NHCOO⁻), which form salt bridges stabilising T-state. (2) H⁺ binds histidine residues (especially His146 of β-chains) in T-state, raising pKa of these residues. Both effects reduce O₂ affinity, facilitating O₂ release in acidic, CO₂-rich tissues."]','A','This allosteric mechanism links tissue metabolic activity directly to haemoglobin O₂ affinity — the more a tissue metabolises (producing CO₂ and H⁺), the more Hb releases O₂ to that tissue. It is a classic example of physiological elegance.','universal',false,'{year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','hard','flashcard','What is cyanosis, and when does it appear clinically?','["Cyanosis is a bluish discolouration of skin and mucous membranes due to increased reduced (deoxygenated) haemoglobin in capillary blood. Central cyanosis: reduced SaO₂ → reduced Hb throughout circulation; best seen on tongue and mucous membranes. Peripheral cyanosis: increased O₂ extraction in periphery (poor perfusion); warm central areas (tongue) are normal. Cyanosis becomes clinically detectable when absolute deoxyHb ≥ 5 g/dl in capillary blood."]','A','Key caveat: cyanosis is absent in anaemia (insufficient total Hb to reach 5 g/dl deoxyHb — even fully desaturated Hb in anaemia may only be 3–4 g/dl). Conversely, polycythaemia can cause cyanosis at relatively high SaO₂. Cyanosis is an unreliable marker of O₂ status — always check SpO₂ and/or ABG.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Oxygen Transport','hard','flashcard','Explain the concept of O₂ supply dependency and critical DO₂ in shock states.','["Normally, O₂ consumption (VO₂) is independent of O₂ delivery (DO₂) above a critical threshold (DO₂ ~300 ml/min) — tissues increase O₂ extraction as DO₂ falls (O₂ extraction ratio rises from 25% to up to 75%). Below the critical DO₂, tissues cannot extract enough O₂ → VO₂ falls with DO₂ (O₂ supply dependency) → anaerobic metabolism → lactic acidosis. In sepsis/ARDS, the critical DO₂ may be elevated and extraction may be impaired (pathological supply dependency)."]','A','Clinical target: maintain DO₂ > critical threshold by optimising CO (fluids, inotropes), Hb (transfusion target varies by context), and SaO₂ (supplemental O₂). Mixed venous SvO₂ < 65% suggests inadequate DO₂ relative to VO₂.','universal',true,'{year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','easy','flashcard','Summarise the three forms of CO₂ transport in blood and their proportions.','["(1) Dissolved CO₂ in plasma: ~7–10% (CO₂ is more soluble than O₂ — 0.03 mmol/L/mmHg); (2) Carbamino compounds (CO₂ bound to amine groups of Hb and plasma proteins): ~20–23%, especially deoxy-Hb (Haldane effect); (3) Bicarbonate (HCO₃⁻): ~70% — formed in RBCs by carbonic anhydrase (CO₂ + H₂O ↔ H₂CO₃ ↔ HCO₃⁻ + H⁺), HCO₃⁻ exits via AE1 exchanger (chloride shift)."]','A','Mnemonic: ''70-23-7'' — HCO₃⁻ (70%), Carbamino (23%), dissolved (7%). The Haldane effect means more CO₂ is carried in the venous (deoxygenated) form — deoxygenation in tissues promotes CO₂ loading; oxygenation in lungs promotes CO₂ offloading.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','easy','flashcard','Define the bicarbonate buffer system and the Henderson-Hasselbalch equation.','["The bicarbonate buffer system: CO₂ + H₂O ↔ H₂CO₃ ↔ H⁺ + HCO₃⁻. Henderson-Hasselbalch: pH = 6.1 + log([HCO₃⁻] / 0.03 × PCO₂). At normal values: pH = 6.1 + log(24 / 0.03 × 40) = 6.1 + log(24/1.2) = 6.1 + log(20) = 6.1 + 1.30 = 7.40. Lungs control PCO₂ (rapidly, seconds-minutes); kidneys control HCO₃⁻ (slowly, hours-days)."]','A','The ratio [HCO₃⁻] / (0.03 × PCO₂) determines pH — it must equal 20 for pH 7.40. Any acid-base disturbance can be understood as a change in this ratio. Compensation always moves the ratio back toward 20.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','medium','flashcard','Explain the Haldane effect and its physiological role in CO₂ transport.','["The Haldane effect: deoxygenated haemoglobin (deoxy-Hb) carries more CO₂ than oxygenated Hb, by two mechanisms: (1) Deoxy-Hb is a better buffer (accepts H⁺ generated during HCO₃⁻ formation); (2) Deoxy-Hb''s amino groups bind CO₂ more readily as carbamino compounds. In peripheral tissues: Hb deoxygenates → CO₂ loading facilitated. In pulmonary capillaries: Hb oxygenates → H⁺ released → shifts HCO₃⁻ back to CO₂ for exhalation; carbamino-CO₂ released."]','A','The Haldane and Bohr effects are complementary: Bohr effect promotes O₂ unloading in tissues; Haldane effect promotes CO₂ loading in tissues. Both are reversed in the lungs to optimise gas exchange.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','medium','flashcard','Describe the systemic and renal compensation for respiratory acidosis.','["Respiratory acidosis: primary ↑PaCO₂ → ↓pH. Immediate buffering: H⁺ is buffered intracellularly by proteins and phosphates, raising HCO₃⁻ slightly (~1 mEq/L per 10 mmHg ↑PCO₂). Chronic renal compensation (2–5 days): kidneys ↑H⁺ secretion (via H⁺-ATPase and H⁺-K⁺-ATPase in collecting duct), ↑HCO₃⁻ reabsorption, ↑ammoniagenesis → HCO₃⁻ rises ~3.5 mEq/L per 10 mmHg ↑PCO₂. pH moves toward (rarely to) normal."]','A','In COPD with chronic hypercapnia, expected HCO₃⁻ = 24 + 3.5 × [(PaCO₂ − 40)/10]. If HCO₃⁻ is higher than expected, suspect concurrent metabolic alkalosis (e.g., diuretics). If lower, suspect concurrent metabolic acidosis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','medium','flashcard','How does the respiratory system compensate for metabolic acidosis?','["Metabolic acidosis: primary ↓HCO₃⁻ → ↓pH. H⁺ stimulates peripheral and central chemoreceptors → hyperventilation → ↓PaCO₂ → ↑pH (moves ratio back toward 20). Kussmaul breathing (deep, rapid) is the clinical manifestation (e.g., diabetic ketoacidosis). Expected respiratory compensation (Winter''s formula): PaCO₂ = 1.5 × [HCO₃⁻] + 8 (± 2). Compensation begins within minutes, maximally complete in 12–24 hours."]','A','Winter''s formula is clinically essential. If actual PaCO₂ is HIGHER than predicted: concurrent respiratory acidosis. If LOWER than predicted: concurrent respiratory alkalosis. Never over-compensate to alkalosis — this is a limit.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','medium','flashcard','Explain the acid-base changes and mechanism in metabolic alkalosis from vomiting.','["Vomiting causes loss of HCl from the stomach → loss of H⁺ and Cl⁻ from the body. Direct effect: ↑plasma HCO₃⁻ (for each H⁺ lost, one HCO₃⁻ remains) → ↑pH → metabolic alkalosis. Respiratory compensation: hypoventilation → ↑PaCO₂ (expected: PaCO₂ = 40 + 0.7 × [ΔHCO₃⁻]). Renal: normally rapidly excretes excess HCO₃⁻, BUT: volume depletion (from vomiting) → angiotensin II/aldosterone → avid NaCl reabsorption → H⁺ secretion maintained to reabsorb Na⁺ (contraction alkalosis perpetuated)."]','A','Paradoxical aciduria: despite metabolic alkalosis, urine pH may be acidic because kidneys prioritise volume (Na⁺/H₂O) over pH balance. Treatment: IV normal saline (restores Cl⁻ and volume, allowing kidney to excrete HCO₃⁻).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','hard','flashcard','Explain why giving high-flow O₂ to a COPD patient with chronic CO₂ retention can worsen hypercapnia.','["In chronic COPD with CO₂ retention, central chemoreceptors are reset to the elevated PaCO₂ baseline. The remaining ventilatory drive comes from: (1) Hypoxic drive (peripheral carotid body chemoreceptors responding to low PaO₂); (2) The Haldane effect — O₂ therapy reverses the Haldane effect, displacing CO₂ from Hb back into plasma, raising PaCO₂ (''Haldane effect-mediated hypercapnia''); (3) Relieving HPV in hypoventilated areas → more blood to those units → V/Q worsens. Correcting hypoxia too rapidly removes the peripheral drive."]','A','Target SpO₂ 88–92% in COPD patients with known or suspected CO₂ retention (BTS guidelines). Use controlled O₂ (24–28% Venturi mask). The Haldane effect may account for more of the rise in PaCO₂ than removal of hypoxic drive in some patients.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','hard','flashcard','What is the anion gap and how does it help classify metabolic acidosis?','["Anion gap (AG) = Na⁺ − (Cl⁻ + HCO₃⁻). Normal = 8–12 mEq/L (unmeasured anions: albumin, phosphate, sulphate, organic acids). Elevated AG metabolic acidosis (MUDPILES): Methanol, Uraemia, Diabetic ketoacidosis, Paracetamol/Propylene glycol, Iron/Isoniazid, Lactic acidosis, Ethylene glycol, Salicylates. Normal AG metabolic acidosis (hyperchloraemic): diarrhoea (HCO₃⁻ loss), RTA, fistulae, acetazolamide. Respiratory acidosis does NOT elevate the AG."]','A','Albumin correction: For every 1 g/dl fall in albumin below 4 g/dl, subtract 2.5 from the normal AG. In hypoalbuminaemia, a ''normal'' AG may actually represent a masked elevated AG metabolic acidosis (e.g., sepsis with hypoalbuminaemia).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','hard','flashcard','Explain the buffering role of haemoglobin in blood pH regulation.','["Haemoglobin is the most important non-bicarbonate buffer in blood, accounting for ~80% of non-bicarbonate buffering capacity. Mechanism: Hb has multiple ionisable histidine residues (pKa ~6.5–8.0) that can accept or donate H⁺ over the physiological pH range. Key property: deoxy-Hb (pKa of His146β ~8.0) is a better proton acceptor than oxy-Hb (pKa ~6.7). When Hb deoxygenates in tissues, it accepts H⁺ generated during CO₂→HCO₃⁻ conversion, buffering the pH fall."]','A','This is the molecular basis of the Haldane effect''s buffering component. Hb buffering is instantaneous (unlike renal compensation taking days) and is why patients with severe anaemia have reduced buffering capacity and are more vulnerable to rapid pH swings.','universal',false,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','CO2 Transport & Acid-Base','hard','flashcard','How does acute mountain sickness (AMS) relate to respiratory alkalosis and cerebral effects?','["At high altitude: low PaO₂ → peripheral chemoreceptor stimulation → hyperventilation → ↓PaCO₂ → respiratory alkalosis. Brain effects: (1) Alkalosis causes cerebral vasoconstriction (CO₂ normally vasodilates cerebral vessels) → reduced cerebral blood flow → headache, dizziness; (2) Simultaneously, hypoxia causes cerebral vasodilation. Net effect is complex, but AMS = headache + ≥1 of: fatigue, dizziness, nausea, sleep disturbance. HACE (high altitude cerebral oedema) is life-threatening — cerebral oedema from BBB disruption."]','A','Treatment of AMS: descent (definitive), dexamethasone (reduces cerebral oedema), acetazolamide (promotes acclimatisation by renal HCO₃⁻ excretion, acidifying plasma → stimulates ventilation). Portable hyperbaric bags (Gamow bags) can temporise in the field.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','easy','flashcard','Describe West''s three zones of the lung and the pressure relationships in each.','["Zone 1 (apex): PA > Pa > Pv — alveolar pressure exceeds arterial pressure; capillaries collapsed; no flow (alveolar dead space). Zone 2 (mid): Pa > PA > Pv — arterial pressure exceeds alveolar; intermittent flow proportional to Pa−PA; Starling resistor (waterfall effect). Zone 3 (base): Pa > Pv > PA — both arterial and venous pressures exceed alveolar; continuous flow throughout cardiac cycle; flow = Pa−Pv. PA = alveolar pressure, Pa = pulmonary arterial pressure, Pv = pulmonary venous pressure."]','A','Memory: In Zone 1 — All Pressure from Air wins; Zone 2 — Arterial overcomes Alveolar; Zone 3 — all pressures exceed Alveolar so flow is continuous. Zone 4 exists at very high lung volumes (interstitial pressure compresses extra-alveolar vessels).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','easy','flashcard','Explain hypoxic pulmonary vasoconstriction (HPV) — mechanism, stimulus, and benefit.','["HPV is a unique response of the pulmonary vasculature: low alveolar PO₂ (PAO₂ < ~70 mmHg) causes adjacent pulmonary arterioles to constrict. Mechanism: hypoxia inhibits voltage-gated K⁺ channels in pulmonary arterial smooth muscle cells → membrane depolarisation → L-type Ca²⁺ channel opening → vasoconstriction. Also involves ROS, endothelin-1. Physiological benefit: diverts blood from poorly ventilated (low V/Q) alveoli to better-ventilated regions, optimising V/Q matching."]','A','HPV is the OPPOSITE of the systemic response (where hypoxia causes vasodilation). This is physiologically perfect: pulmonary circulation routes blood to where O₂ is; systemic circulation routes blood to where O₂ is needed. Anaesthetic agents, calcium channel blockers, and nitric oxide inhibit HPV, worsening V/Q mismatch.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','medium','flashcard','How does pulmonary arterial hypertension (PAH) develop in chronic lung disease and what are its consequences?','["Chronic hypoxia (COPD, ILD, altitude) → sustained HPV → smooth muscle hypertrophy and intimal proliferation in pulmonary arterioles → fixed elevated PVR → PAH (mean PA pressure >25 mmHg at rest). Consequences: (1) Increased RV afterload → RV hypertrophy → cor pulmonale; (2) RV dilation → D-shaped interventricular septum (shifts toward LV) → impaired LV filling → reduced cardiac output; (3) Tricuspid regurgitation; (4) Right heart failure → oedema, ascites, raised JVP."]','A','''Cor pulmonale'' = RV failure due to lung disease (not LV failure). Signs: raised JVP, peripheral oedema, hepatomegaly, parasternal heave, loud P2, tricuspid regurgitation murmur. ECG: right axis deviation, right bundle branch block, P pulmonale.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','medium','flashcard','Why is the V/Q ratio highest at the lung apex and lowest at the base in an upright person?','["Both ventilation (V) and perfusion (Q) increase from apex to base in the upright lung due to gravity. However, perfusion increases more steeply (~5-fold apex to base) than ventilation (~2–3 fold apex to base). At the apex: low Q relative to V → high V/Q (~3.3). At the base: high Q relative to V → low V/Q (~0.6). The perfusion gradient is steeper because pulmonary arterial pressure is relatively low, making it more susceptible to gravitational pressure differences."]','A','Consequence: apical alveoli have high PAO₂ (~130 mmHg) and low PACO₂ (~28 mmHg) — near inspired air composition. Basal alveoli have lower PAO₂ (~89 mmHg) and higher PACO₂ (~42 mmHg). The overall arterial blood is a weighted average (perfusion-weighted), so it resembles basal blood more.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','medium','flashcard','Describe the Starling forces governing fluid exchange in pulmonary capillaries and how oedema develops.','["Starling equation: Net filtration = Kf[(Pc − Pi) − σ(πc − πi)], where Pc = capillary hydrostatic pressure (~8 mmHg), Pi = interstitial hydrostatic pressure (~−8 mmHg), πc = capillary oncotic pressure (~28 mmHg), πi = interstitial oncotic pressure (~14 mmHg). Net: slight filtration from capillary to interstitium → drained by lymphatics. Oedema occurs when: (1) Pc rises (left heart failure, ARDS); (2) πc falls (hypoalbuminaemia); (3) Capillary permeability ↑ (ARDS, infection); (4) Lymphatic obstruction."]','A','In cardiogenic pulmonary oedema: PCWP > 18 mmHg → hydrostatic oedema (low-protein fluid). In ARDS/non-cardiogenic: normal PCWP but ↑capillary permeability → high-protein exudate. Distinguishing is critical for management.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','medium','flashcard','What are the consequences of one-lung ventilation (OLV) during thoracic surgery for V/Q matching?','["During OLV (e.g., lobectomy/pneumonectomy), the operative (non-ventilated) lung collapses → V = 0 → V/Q = 0 → blood passing through creates a true right-to-left shunt. This shunt fraction can be 20–30% of cardiac output. Compensating mechanisms: (1) HPV in the non-ventilated lung reduces blood flow to it; (2) Lateral decubitus position (operative lung up) reduces its perfusion by gravity; (3) Clamping the operative pulmonary artery (if done early) eliminates the shunt."]','A','HPV is the key protective mechanism during OLV. Drugs inhibiting HPV (volatile anaesthetics, Ca²⁺-channel blockers) worsen hypoxaemia during OLV. TIVA (total intravenous anaesthesia with propofol) preserves HPV better than volatile agents and may improve OLV oxygenation.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','hard','flashcard','Explain how prone positioning improves oxygenation in ARDS.','["In ARDS (supine): dorsal lung regions are dependent → compressive atelectasis from mediastinum and abdominal viscera → V/Q = 0 → shunt. Ventral regions are non-dependent → aerated but over-distended. In prone position: (1) Dorsal (now non-dependent) regions re-aerate and recruit; (2) Ventral (now dependent) regions partially collapse — but these were already aerated, so overall V/Q mismatch and shunt decrease; (3) Perfusion redistributes more evenly; (4) Secretion drainage improves; (5) Functional recruitment increases EELV."]','A','PROSEVA trial (2013): >16 hours/day prone positioning in severe ARDS (P/F < 150) reduced 28-day mortality from 32.8% to 16.0% (p<0.001). Prone positioning is now standard of care for severe ARDS. Contraindications: unstable spinal injuries, open abdomen, facial fractures.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','hard','flashcard','How does nitric oxide (NO) selectively vasodilate perfused pulmonary vessels and improve V/Q matching?','["Inhaled NO is a selective pulmonary vasodilator. It diffuses from alveoli into the adjacent pulmonary arteriolar smooth muscle → activates guanylyl cyclase → ↑cGMP → smooth muscle relaxation → vasodilation. Crucially, NO only reaches arterioles adjacent to VENTILATED alveoli (it is inhaled with air). Non-ventilated lung units receive no NO → HPV is preserved in those areas. This selectively increases perfusion to ventilated areas, improving V/Q matching without systemic vasodilation (NO is inactivated by Hb in the bloodstream)."]','A','Inhaled NO improves oxygenation in ARDS and primary PAH. However, it has not shown mortality benefit in ARDS trials (possibly because it causes methemoglobinaemia at high doses and rebound vasoconstriction when stopped). Used as a bridge to other therapies.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','hard','flashcard','Describe the haemodynamic consequences of a massive pulmonary embolism on the right ventricle.','["Massive PE (>50% pulmonary artery obstruction): acute rise in PVR → acute RV pressure overload → RV dilation → RV wall stress ↑ → myocardial ischaemia (RCA compression + increased O₂ demand) → RV failure. LV effects: (1) Reduced pulmonary venous return → reduced LV preload → low CO + hypotension; (2) Interventricular septal shift (D-sign) further impairs LV filling. McConnell''s sign on echo: RV free wall hypokinesia with apical sparing (relatively specific for PE)."]','A','Massive PE management: systemic thrombolysis (alteplase 100 mg over 2 hours) if no contraindications; surgical embolectomy or catheter-directed thrombolysis if thrombolysis contraindicated. Vasopressors (norepinephrine) for hypotension; AVOID aggressive fluids (worsen RV dilation).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','V/Q Matching & Pulmonary Blood Flow','hard','flashcard','What is hepatopulmonary syndrome (HPS) and how does it produce V/Q mismatch?','["HPS: a triad of (1) liver disease/portal hypertension; (2) intrapulmonary vascular dilatations (IPVDs); (3) hypoxaemia. Mechanism: portal hypertension → increased NO production (via bacterial translocation stimulating NOS in pulmonary vasculature) → pulmonary vascular dilatation. IPVDs create shunt (V/Q = 0 for AV connections) and diffusion limitation (O₂ cannot reach RBCs in dilated, wide capillaries). Clinical hallmark: orthodeoxia (PaO₂ falls on standing — basilar IPVDs worsen; improves supine)."]','A','Confirmed by: contrast echocardiography (bubbles appear in left heart after >3 beats in right heart — normal passage is <3 beats). Treatment: liver transplantation is the only definitive cure. Supplemental O₂ and TIPS may temporarily improve oxygenation.','universal',true,'{year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','easy','flashcard','Describe the organisation of the respiratory control centres in the brainstem.','["Medulla: (1) Dorsal Respiratory Group (DRG) — in nucleus tractus solitarius (NTS); houses pre-Bötzinger complex (rhythmogenic pacemaker); drives inspiratory activity via phrenic and intercostal motor neurons. (2) Ventral Respiratory Group (VRG) — active during forceful breathing; controls accessory muscle recruitment and abdominal/expiratory muscles. Pons: (1) Pneumotaxic centre (nucleus parabrachialis, upper pons) — limits inspiration, increases RR. (2) Apneustic centre (lower pons) — prolongs inspiration (normally overridden by pneumotaxic centre)."]','A','Memory: ''PAD'' from bottom to top: Pre-Bötzinger/DRG (medulla), Apneustic (lower pons), pneumotaxic centre at the top of the Pons. Cerebral cortex overrides automatic control (voluntary breath-holding, voluntary hyperventilation).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','easy','flashcard','What do central chemoreceptors respond to, and where are they located?','["Central chemoreceptors are located on the ventrolateral surface of the medulla (near the chemosensitive area). They respond to changes in H⁺ concentration of cerebrospinal fluid (CSF). CO₂ crosses the blood-brain barrier (BBB) freely; in CSF it forms H₂CO₃ → H⁺ + HCO₃⁻ (via carbonic anhydrase). The resulting fall in CSF pH stimulates the chemoreceptors → increased ventilation. They do NOT directly sense PO₂. They account for ~70% of the ventilatory response to CO₂."]','A','The BBB is relatively impermeable to H⁺ and HCO₃⁻ but freely permeable to CO₂. This is why CO₂ is a more potent stimulus to ventilation than systemic metabolic acidosis (H⁺ cannot cross the BBB rapidly). Over 24–48 hours, CSF HCO₃⁻ can change to partially normalise CSF pH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','medium','flashcard','Describe the peripheral chemoreceptors — location, sensing mechanism, and stimuli.','["Location: carotid bodies (at common carotid artery bifurcation; transmit via CN IX glossopharyngeal → NTS) and aortic bodies (near aortic arch; transmit via CN X vagus → NTS). Carotid bodies dominate in humans. Sensing: Type I (glomus) cells sense low PaO₂, high PaCO₂, and low pH; depolarise via inhibited K⁺ channels → release dopamine/acetylcholine → activate afferent nerve. Stimuli by potency: PaCO₂ rise > pH fall > PaO₂ fall (PaO₂ must fall below ~60 mmHg for significant stimulation)."]','A','Key distinction: peripheral chemoreceptors are responsible for the ENTIRE ventilatory response to hypoxia (central chemoreceptors do not sense O₂). In bilateral carotid body resection (e.g., for glomus tumour), the hypoxic ventilatory response is abolished but CO₂ response is largely preserved.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','medium','flashcard','What is the ventilatory response to CO₂ and how is it altered by disease and drugs?','["Ventilatory response to CO₂: for each mmHg rise in PaCO₂ above ~37 mmHg, ventilation increases by ~2–3 L/min (approximately linear). This response is mediated 70% by central and 30% by peripheral chemoreceptors. Blunted CO₂ response in: chronic hypercapnia (COPD — CSF HCO₃⁻ adaptation), opioids (reduce central chemoreceptor sensitivity), benzodiazepines, severe hypothyroidism, obesity hypoventilation syndrome (OHS). Enhanced: salicylates (at toxic doses), progesterone."]','A','Opioids and benzodiazepines primarily depress the central CO₂ response — the hallmark of their respiratory toxicity. Naloxone reverses opioid respiratory depression. Progesterone-mediated hyperventilation explains reduced PaCO₂ in pregnancy (~30 mmHg in 3rd trimester).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','medium','flashcard','Explain the Hering-Breuer inflation reflex and its clinical relevance.','["The Hering-Breuer inflation reflex: as lung volume increases with each breath, slowly adapting stretch receptors (SARs) in airway smooth muscle are activated. Impulses travel via vagus nerve (CN X) afferents to the NTS → inhibit the inspiratory neurons → terminate inspiration (inspiratory off-switch). This prevents excessive lung inflation. In anaesthetised adults and infants, this reflex is prominent. In conscious adults, it plays a minimal role in normal breathing but becomes important with large Vt."]','A','Clinical relevance: (1) Basis of Hering-Breuer-triggered breathing patterns in some ventilators (pressure support ventilation uses flow cycling rather than SAR-based timing). (2) Bilateral vagotomy (or vagal block during thoracic surgery) can cause slow, deep breathing with high Vt.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','medium','flashcard','How does the body control breathing during sleep, and why are some patients at particular risk?','["During NREM sleep: ventilatory drive decreases, PaCO₂ rises slightly (~2–3 mmHg), PaO₂ falls slightly. Upper airway muscle tone decreases, increasing upper airway resistance. During REM sleep: breathing becomes irregular (''REM breathing''); skeletal muscle atonia (including intercostals); breathing maintained mainly by diaphragm; no response to auditory arousal. Patients at risk: severe COPD (reduced respiratory reserve; REM-related desaturation), neuromuscular disease (diaphragm dependence during REM), OHS, and OSA."]','A','Nocturnal non-invasive ventilation (NIV/BiPAP) is indicated in patients with severe nocturnal hypoventilation (e.g., Duchenne muscular dystrophy, severe COPD with nocturnal SpO₂ <88% for >30% of recording time, OHS with PaCO₂ >45 mmHg).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','hard','flashcard','Explain the neurophysiology of the pre-Bötzinger complex as the respiratory pacemaker.','["The pre-Bötzinger complex (preBötC) is a cluster of interneurons in the ventrolateral medulla (within the VRG) that generates the inspiratory rhythm via intrinsic pacemaker properties (persistent Na⁺ channels, Ca²⁺-activated nonselective cation channels) and network burst activity. Excitatory interneurons within the preBötC excite each other and the inspiratory motor neurons, then burst activity is terminated by inhibitory post-inspiratory neurons and slowly adapting lung stretch receptor feedback. The rhythm is modulated but not generated by pontine centres."]','A','The preBötC was identified by Feldman et al. in 1991. Lesioning the preBötC in animals abolishes breathing. It is intrinsically rhythmic even in brainstem slice preparations in vitro — making it a true pacemaker. Understanding it is key to developing treatments for central apnoea.','universal',false,'{year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','hard','flashcard','Describe the ventilatory control abnormality in obesity hypoventilation syndrome (OHS) and its management.','["OHS: BMI >30 + PaCO₂ >45 mmHg (daytime hypercapnia) in the absence of other causes. Mechanisms: (1) Increased work of breathing (WOB) from obesity-related restriction; (2) Leptin resistance — leptin normally stimulates ventilation via hypothalamic receptors; obese patients have high leptin levels but central resistance; (3) Blunted central chemoreceptor CO₂ response (adaptation to chronic hypercapnia); (4) Coexisting OSA worsening nocturnal hypoventilation. Most develop during sleep first (nocturnal hypoventilation → daytime CO₂ retention)."]','A','Management: Weight loss (definitive); NIV (bilevel PAP/BiPAP) with a backup rate — provides ventilatory support during sleep, reduces nocturnal hypoventilation, and over time can partially restore CO₂ chemosensitivity. Distinguishing OHS from simple OSA on CPAP is important (OHS needs BiPAP, not just CPAP).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','hard','flashcard','What is the phenomenon of ''post-hyperventilation apnoea'' and why is it dangerous?','["Post-hyperventilation apnoea occurs when deliberate or reflex hyperventilation lowers PaCO₂ well below the ''apnoeic threshold'' (~35 mmHg). If PaCO₂ falls below this threshold, the respiratory drive from central chemoreceptors is eliminated, and breathing stops until PaCO₂ rises back above the threshold. Duration of apnoea depends on how far PaCO₂ fell and the rate of CO₂ production. During the apnoea, if PaO₂ also falls low enough, loss of consciousness (especially during swimming/diving) can cause drowning before CO₂ rises to trigger breathing."]','A','The apnoeic threshold is ~35 mmHg — just below normal resting PaCO₂. During assisted ventilation, if the ventilator drives PaCO₂ below 35, spontaneous breathing is suppressed. This must be considered when transitioning patients from controlled to spontaneous ventilation modes.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Control of Breathing','hard','flashcard','How does the body adapt ventilatory control to sustained hypoxia over days (acclimatisation)?','["Day 0: Low PaO₂ → carotid body stimulation → hyperventilation → ↓PaCO₂ → respiratory alkalosis → partially inhibits further ventilation (CSF alkalinity dampens central drive). Days 1–4: Kidneys excrete HCO₃⁻ → CSF and blood pH normalise → central chemoreceptor inhibition removed → peripheral carotid body-driven hyperventilation proceeds unchecked → PaCO₂ falls further (to 30–35 mmHg on high mountains) → PAO₂ rises further. Simultaneously: EPO ↑ → polycythaemia; ↑2,3-DPG; ↑pulmonary diffusing capacity."]','A','The acclimatisation time course explains why mountaineers must ascend slowly. The ventilatory acclimatisation is largely mediated by: (1) carotid body sensitisation (increased O₂-sensing sensitivity); (2) renal HCO₃⁻ excretion allowing sustained hypoxic ventilatory drive. Acetazolamide accelerates renal adaptation.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','easy','flashcard','How does ventilation change during exercise and what are the key controlling mechanisms?','["Three phases: (1) Immediate onset: rapid ↑ventilation within seconds of starting exercise (before blood gas changes) — mediated by cortical irradiation (motor cortex to respiratory centres) and joint/muscle proprioceptors. (2) Moderate exercise: sustained hyperventilation matched to metabolic rate; PaO₂, PaCO₂, and pH remain nearly normal — the oscillations in CO₂ delivery stimulate peripheral chemoreceptors; (3) Heavy exercise (above anaerobic threshold): additional lactic acidosis → H⁺ stimulates chemoreceptors → VE/VCO₂ rises → respiratory compensation; PaCO₂ may fall below 40 mmHg."]','A','During moderate exercise, the precision of V-metabolism matching is remarkable — PaO₂, PaCO₂, and pH are nearly unchanged despite 10–20× increase in ventilation. The mechanism is not fully explained but likely involves CO₂ oscillations and neurogenic stimulation acting in synergy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','easy','flashcard','Summarise the immediate and delayed physiological adaptations to high altitude.','["Immediate (hours): ↑ventilation (peripheral chemoreceptors); ↑HR and CO; ↑EPO secretion begins; acute mountain sickness may occur. Short-term (days): renal HCO₃⁻ excretion → pH normalises → sustained hyperventilation; ↑2,3-DPG; ↑pulmonary diffusing capacity (capillary recruitment). Long-term (weeks): polycythaemia (↑Hb and haematocrit); RV hypertrophy (from HPV-induced PAH); right shift of O₂-Hb curve (2,3-DPG); chronic HPV → cor pulmonale in those with maladaptation."]','A','Native high-altitude populations (Tibetans, Andeans, Ethiopians) have evolved distinct adaptive strategies: Tibetans maintain lower Hb but higher NO levels; Andeans develop polycythaemia (Monge''s disease); Ethiopians maintain near sea-level PaO₂ via enhanced ventilatory response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','medium','flashcard','What respiratory changes occur during pregnancy and what is their physiological basis?','["Progesterone directly stimulates the medullary respiratory centres → ↑tidal volume (~40%), ↑alveolar ventilation → ↓PaCO₂ (to ~30 mmHg) → mild respiratory alkalosis → renal HCO₃⁻ excretion → HCO₃⁻ falls to ~20 mEq/L (compensated respiratory alkalosis). FRC decreases (~20%) due to elevated diaphragm from the enlarging uterus. Minute ventilation ↑40%. Oxygen consumption ↑20%. Net: pregnant women have mild respiratory alkalosis, low PaCO₂, and lower FRC."]','A','Clinical importance: (1) ↓FRC means faster desaturation during apnoea (e.g., induction of anaesthesia) — rapid pre-oxygenation essential; (2) Normal PaCO₂ in a pregnant woman is ~30 mmHg — a PaCO₂ of 40 mmHg indicates respiratory failure in pregnancy; (3) Dyspnoea of pregnancy is common and physiological.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','medium','flashcard','Describe the respiratory response to acute metabolic acidosis (e.g., diabetic ketoacidosis).','["Metabolic acidosis → ↑plasma H⁺ → stimulates peripheral chemoreceptors (immediately) and central chemoreceptors (as H⁺ slowly crosses BBB) → hyperventilation (Kussmaul breathing: deep, rapid, laboured respirations) → ↓PaCO₂ → respiratory compensation. Kussmaul breathing can reduce PaCO₂ to 10–15 mmHg in severe acidosis. Winter''s formula: expected PaCO₂ = (1.5 × [HCO₃⁻]) + 8 ± 2. If actual PaCO₂ > predicted: concurrent respiratory acidosis; if < predicted: concurrent respiratory alkalosis."]','A','DKA hallmarks: hyperglycaemia, anion gap metabolic acidosis, ketonaemia/ketonuria, Kussmaul breathing, fruity breath (acetone). Respiratory compensation cannot fully correct pH (limited by minimum PaCO₂ ~10 mmHg); definitive treatment is insulin to stop ketogenesis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','medium','flashcard','How do the lungs respond to increased CO₂ production during fever?','["Fever increases cellular metabolic rate → ↑CO₂ production (VCO₂). If ventilation does not change, PaCO₂ would rise → respiratory acidosis. In healthy individuals: ↑CO₂ delivery to central and peripheral chemoreceptors → ↑ventilation proportionally → PaCO₂ maintained near 40 mmHg. Additionally, temperature itself activates peripheral chemoreceptors and hypothalamic projections → direct stimulation of respiratory centres. Net effect: tachypnoea proportional to the degree of fever (~increase of 1 breath/min per 1°C rise in temperature)."]','A','The clinical rule of thumb: each 1°C rise in body temperature increases O₂ consumption and CO₂ production by ~10–13%. In patients with limited respiratory reserve (COPD, neuromuscular disease), fever can precipitate hypercapnic respiratory failure — treat the fever aggressively.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','medium','flashcard','What is the respiratory response to acute blood loss (haemorrhagic shock)?','["Acute blood loss → ↓venous return → ↓CO → ↓O₂ delivery → tissue hypoxia → lactic acidosis → ↑H⁺ stimulates peripheral chemoreceptors → hyperventilation → ↓PaCO₂. Simultaneously: ↓perfusion pressure may move lung from Zone 3 to Zone 1/2, increasing alveolar dead space (worsened by tachycardia reducing transit time). Initially: respiratory alkalosis (from hyperventilation). Later: if CO critically low → metabolic lactic acidosis → mixed picture. Zone 1 creation (if pulmonary artery pressure falls below alveolar) worsens gas exchange."]','A','The classic ABG in haemorrhagic shock: initial respiratory alkalosis (compensatory hyperventilation), then metabolic acidosis (lactic acid accumulation), with rising A-a gradient. Aggressive fluid resuscitation restores CO and pulmonary perfusion, but excessive crystalloid causes pulmonary oedema (dilutes albumin, raises hydrostatic pressure).','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','hard','flashcard','Describe the mechanisms and clinical features of high altitude cerebral oedema (HACE).','["HACE = severe end of AMS spectrum. Pathophysiology: Hypoxia → ↓cellular ATP → Na⁺/K⁺-ATPase failure → cytotoxic oedema (intracellular swelling). Simultaneously: vasogenic oedema from BBB disruption (hypoxia-induced VEGF → ↑permeability). HPV raises intracranial venous pressure. ↑CO (from sympathetic activation) may overperfuse cerebral vasculature bypassing impaired autoregulation. Result: cerebral oedema → raised ICP → headache, ataxia, altered consciousness (''ataxia + altered mental status'' is HACE until proven otherwise). Fundoscopy: papilloedema, retinal haemorrhages."]','A','Management: (1) Immediate descent (most effective); (2) Dexamethasone 8 mg loading dose (reduces vasogenic oedema); (3) Supplemental O₂; (4) Portable hyperbaric chamber (Gamow bag). HACE can progress to coma and death within hours. Acetazolamide prevents but does not adequately treat established HACE.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','hard','flashcard','Explain the integrated respiratory response to maximal dynamic exercise and identify the limiting factor in healthy individuals.','["During maximal exercise (VO₂max): (1) Ventilation rises to 100–180 L/min (tachypnoea + ↑Vt); PaCO₂ may fall (respiratory compensation for lactic acidosis); (2) Cardiac output rises to 20–30 L/min (athletes); (3) Pulmonary capillary transit time falls to 0.25 s; (4) DLCO doubles (capillary recruitment, ↑perfusion pressure); (5) O₂ extraction ratio rises from 25% to ~75%. Limiting factor in healthy individuals: cardiac output (O₂ delivery, not pulmonary gas exchange). Elite athletes may show diffusion limitation at maximal intensity (exercise-induced arterial hypoxaemia)."]','A','In patients with lung disease: the respiratory system becomes the limiting factor (ventilatory limitation: breathing reserve used up; PaO₂ falls; PaCO₂ rises). Cardiopulmonary exercise testing (CPET) distinguishes cardiac vs. respiratory vs. deconditioning limits to exercise.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','hard','flashcard','What is the oxygen cascade and how is it affected at high altitude?','["The O₂ cascade: sequential fall in PO₂ from atmosphere to mitochondria. Atmospheric: 159 mmHg (sea level) → Inspired (humidified): 149 mmHg → Alveolar: ~100 mmHg (PAO₂) → Arterial: ~95 mmHg (A-a gradient ~5 mmHg) → Mixed venous/tissue: ~40 mmHg (O₂ extraction) → Mitochondrial: <5 mmHg (sufficient for oxidative phosphorylation). At 5500 m: PB ~380 mmHg; PAO₂ falls to ~45–50 mmHg; arterial PO₂ ~40 mmHg (on steep part of O₂-Hb curve) → SpO₂ ~70–75%. Mitochondrial PO₂ maintains oxidative function until very low levels (~0.5 mmHg critical PO₂)."]','A','The oxygen cascade explains why even small reductions in alveolar ventilation (hypoventilation at altitude) have dramatically amplified effects on tissue PO₂. Each step in the cascade introduces losses — and altitude reduces the starting pressure, magnifying each step''s proportional cost.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Respiratory System','Anatomy & Physiology','Respiratory Responses','hard','flashcard','Describe the respiratory mechanics and gas exchange changes in ARDS and how they guide ventilator management.','["ARDS: diffuse alveolar damage → ↑capillary permeability → protein-rich exudate fills alveoli → diffuse bilateral consolidation → ↓FRC; ↓CRS (compliance ≤ 40 ml/cmH₂O, normal ~100 ml/cmH₂O); ↑PVR; severe V/Q mismatch and shunt → refractory hypoxaemia (PaO₂/FiO₂ < 300 = ARDS, < 100 = severe). Ventilator strategy (ARDSnet): low Vt (6 ml/kg PBW) to prevent VILI; PEEP to recruit and stabilise alveoli; high FiO₂; permissive hypercapnia acceptable. Plateau pressure < 28 cmH₂O; driving pressure (Pplat − PEEP) < 15 cmH₂O."]','A','The ''baby lung'' concept: in ARDS, only 20–30% of lung is recruitable and normally aerated. Ventilating the whole tidal volume into this small ''baby lung'' causes high alveolar pressure and VILI. Low Vt protects by matching Vt to the available lung volume, not the whole lung weight.','universal',true,'{year3,year4,year5,year6,practitioner}','Guyton & Hall Textbook of Medical Physiology 14th Ed')
